INSERT INTO normalized_profile (normalized_profile_id, version, schema_version, content, validated_at, created_at, updated_at) VALUES ('60e9e55c-1313-514d-b622-b155afa4e838', 1, '1', '{"schemaVersion": "1", "title": "Senior Java Backend Engineer", "alternateTitles": ["Backend Engineer"], "domain": "backend engineering", "contractType": "permanent", "workTime": "full_time", "seniority": "senior", "workMode": "on_site", "location": {"city": "London", "country": "GB"}, "salary": {"min": 62000.0, "max": 88000.0, "currency": "EUR", "period": "year"}, "languages": [{"name": "English", "level": "C1", "required": true}], "summary": "Senior Java Backend Engineer role at Stackline GmbH focusing on backend engineering.", "companyPitch": "We build products people love, with kind teams and high standards.", "description": "We are hiring a Senior Java Backend Engineer to join our backend engineering team. You will own high-impact projects from idea to production. Our backend engineering team is looking for a Senior Java Backend Engineer. Expect real ownership, close collaboration and a fast feedback loop. Core duties: Design and evolve RESTful microservices; Own the PostgreSQL data model and query performance; Operate services on Docker and Kubernetes.", "responsibilities": [{"text": "Design and evolve RESTful microservices", "importance": "mandatory", "domain": "backend engineering", "technologies": ["Java", "Spring Boot", "Hibernate"]}, {"text": "Own the PostgreSQL data model and query performance", "importance": "mandatory", "domain": "backend engineering", "technologies": ["Java", "Spring Boot", "Hibernate"]}, {"text": "Operate services on Docker and Kubernetes", "importance": "mandatory", "domain": "backend engineering", "technologies": ["Java", "Spring Boot", "Hibernate"]}, {"text": "Improve CI/CD pipelines and production observability", "importance": "mandatory", "domain": "backend engineering", "technologies": ["Java", "Spring Boot", "Hibernate"]}, {"text": "Mentor teammates and share knowledge across the squad", "importance": "optional", "domain": "backend engineering", "technologies": []}], "requiredSkills": [{"name": "Java", "category": "programming_language", "level": 3, "levelSource": "declared", "minYears": 0, "origin": "declared", "evidence": [{"source": "responsibility", "index": 0}]}, {"name": "Spring Boot", "category": "framework", "level": 4, "levelSource": "declared", "minYears": 1, "origin": "declared", "evidence": [{"source": "responsibility", "index": 1}]}, {"name": "Hibernate", "category": "framework", "level": 5, "levelSource": "declared", "minYears": 2, "origin": "declared", "evidence": [{"source": "responsibility", "index": 2}]}, {"name": "REST APIs", "category": "technical_skill", "level": 3, "levelSource": "declared", "minYears": 3, "origin": "declared", "evidence": [{"source": "responsibility", "index": 3}]}], "preferredSkills": [{"name": "PostgreSQL", "category": "tool", "level": null, "levelSource": null, "minYears": null, "origin": "declared", "evidence": [{"source": "responsibility", "index": 1}]}, {"name": "Maven", "category": "tool", "level": null, "levelSource": null, "minYears": null, "origin": "declared", "evidence": [{"source": "responsibility", "index": 2}]}], "benefits": ["Remote-friendly policy", "Annual learning budget", "Health insurance"]}'::jsonb, '2026-09-04 13:00:00', '2026-09-04 13:00:00', '2026-09-04 13:00:00');
